{
  "name": "@candelahq/opencode",
  "version": "0.8.2",
  "description": "OpenCode plugin for Candela — conversational cost queries, budget tracking, model configuration, and LLM observability",
  "type": "module",
  "main": "dist/index.js",
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "npm run build",
    "test": "vitest run",
    "test:watch": "vitest",
    "lint": "biome check src/",
    "lint:fix": "biome check --write src/",
    "format": "biome format --write src/"
  },
  "types": "dist/index.d.ts",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "candela",
    "llm",
    "observability",
    "cost-tracking",
    "ai"
  ],
  "author": "Candela HQ",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "https://github.com/candelahq/opencode-candela.git"
  },
  "homepage": "https://candelahq.com",
  "bugs": {
    "url": "https://github.com/candelahq/opencode-candela/issues"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*",
    "@opentui/core": ">=0.2.11",
    "@opentui/solid": ">=0.2.11",
    "solid-js": "^1.9.12"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@biomejs/biome": "^2.0.0",
    "@opencode-ai/plugin": "latest",
    "@opentui/core": "0.4.3",
    "@opentui/solid": "0.4.3",
    "@types/node": "^25.8.0",
    "solid-js": "1.9.12",
    "typescript": "^5.8.0",
    "vitest": "^4.1.10"
  },
  "files": [
    "dist/",
    "README.md",
    "CHANGELOG.md"
  ]
}
